public class JArrayBasic3
{
   public static void main (String[] args)
   {
	  //#Paso 1: Define un arreglo de cuatro cadenas
	   String[] lst = {"manana", "mediodia", "tarde", "noche"};
	   //Paso 2: Actualiza el elemento del arreglo
	   lst[3] = "medianoche";
	   //Paso 3: Imprime los elementos del arreglo
	   for (String x : lst) {
		   System.out.print(x + "  ");
	   }
   }
}

